contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 collateralAmount, bool doTransfer) public payable {
        require(amount > 0, "amount zero");
        require(collateralAmount > 0, "collateral zero");
        require(doTransfer, "must transfer");

        uint256 beforeLp = c.getmapAddress_LPBalance(address(this));
        uint256 beforeDebt = c.getmapAddress_LPDebt(address(this));
        uint256 beforeSupply = c.totalSupply();
        if (doTransfer) {
            c.transfer(address(this), collateralAmount);
        }
        c.mintSynth(address(this), amount);
        uint256 afterLp = c.getmapAddress_LPBalance(address(this));
        uint256 afterDebt = c.getmapAddress_LPDebt(address(this));
        uint256 afterSupply = c.totalSupply();

        assert(afterLp >= beforeLp && afterDebt >= beforeDebt && afterSupply >= beforeSupply);

        uint256 lpDelta = afterLp - beforeLp;
        uint256 debtDelta = afterDebt - beforeDebt;
        uint256 supplyDelta = afterSupply - beforeSupply;

        assert(lpDelta >= collateralAmount && debtDelta >= amount && supplyDelta >= amount);
    }

    receive() external payable {}
}

