contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0), "!recipient");
        require(recipient != address(this), "!self");

        uint256 beforeSupply = c.totalSupply();
        uint256 beforeSenderBal = c.balanceOf(address(this));
        uint256 beforeRecipientBal = c.balanceOf(recipient);
        require(beforeSenderBal >= amount, "!balance");

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterSupply = c.totalSupply();
        uint256 afterSenderBal = c.balanceOf(address(this));
        uint256 afterRecipientBal = c.balanceOf(recipient);

        assert(
            reverted == false
                && afterSupply == beforeSupply
                && afterSenderBal + afterRecipientBal == beforeSenderBal + beforeRecipientBal
                && (recipient != address(this) ? (afterSenderBal == beforeSenderBal - amount && afterRecipientBal == beforeRecipientBal + amount) : true)
        );
    }

    receive() external payable {}
}

