contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(this), "recipient=self not representative");
        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);
        require(amount <= senderBefore, "amount must be within balance to transfer");

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 senderAfter = c.balanceOf(address(this));
            uint256 recipientAfter = c.balanceOf(recipient);
            assert(senderAfter == senderBefore - amount && recipientAfter == recipientBefore + amount);
        } else {
            assert(
                c.balanceOf(address(this)) == senderBefore &&
                c.balanceOf(recipient) == recipientBefore
            );
        }
    }
}

