        bool ok = c.transferFrom(owner, recipient, amount);

        uint256 ownerBalAfter = c.balanceOf(owner);
        uint256 recipientBalAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(owner, spender);

        assert(ok && recipientBalAfter == recipientBalBefore + amount && ownerBalAfter == ownerBalBefore - amount && allowanceAfter == allowanceBefore - amount);
    }

    receive() external payable {}
}

