contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, uint256 amount) public {
        require(spender != address(0), "spender zero");
        uint256 beforeAllowance = c.allowance(address(this), spender);
        if (beforeAllowance == type(uint256).max) {
            // infinite allowance: transferFrom should not change allowance
            bool reverted;
            try c.transferFrom(address(this), spender, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted);
            assert(c.allowance(address(this), spender) == type(uint256).max);
        } else {
            // finite allowance: transferFrom reduces allowance by amount if sufficient
            if (beforeAllowance >= amount) {
                c.transferFrom(address(this), spender, amount);
                assert(c.allowance(address(this), spender) == beforeAllowance - amount);
            } else {
                bool reverted;
                try c.transferFrom(address(this), spender, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
                assert(reverted);
            }
        }
    }
}

