    constructor(C _c) {
        c = _c;
    }

    function run(address spender, uint256 addedValue) public {
        require(spender != address(0), "!spender");
        require(addedValue <= type(uint256).max, "bad addedValue");

        uint256 pre = c.allowance(address(this), spender);

        bool reverted;
        try c.increaseAllowance(spender, addedValue) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 post = c.allowance(address(this), spender);

        if (!reverted) {
            assert(post == pre + addedValue);
        } else {
            assert(post == pre);
        }
    }

    receive() external payable {}
}

