contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0), "bad recipient");

        // Setup: give the caller (this contract) some tokens so a transfer can be attempted.
        c.mintSynth(address(this), amount);

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 senderAfter = c.balanceOf(address(this));
        uint256 recipientAfter = c.balanceOf(recipient);

        assert(
            (!reverted && senderAfter == senderBefore - amount && recipientAfter == recipientBefore + amount)
            ||
            (reverted && senderAfter == senderBefore && recipientAfter == recipientBefore)
        );
    }

    receive() external payable {}
}

