contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, address spender, address recipient, uint256 amount) public payable {
        require(owner != address(0) && spender != address(0) && recipient != address(0), "zero address");
        require(amount > 0, "zero amount");

        c.mintSynth(owner, amount);

        c.approve(spender, amount);

        uint256 allowanceBefore = c.allowance(owner, spender);
        uint256 senderBalanceBefore = c.balanceOf(owner);
        uint256 recipientBalanceBefore = c.balanceOf(recipient);
        uint256 totalSupplyBefore = c.totalSupply();

        bool reverted;
        try c.transferFrom(owner, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balanceOf(owner) == senderBalanceBefore - amount);
            assert(c.balanceOf(recipient) == recipientBalanceBefore + amount);
            assert(c.totalSupply() == totalSupplyBefore);
            assert(c.allowance(owner, spender) == (allowanceBefore < type(uint256).max ? allowanceBefore - amount : allowanceBefore));
        } else {
            assert(c.balanceOf(owner) == senderBalanceBefore);
            assert(c.balanceOf(recipient) == recipientBalanceBefore);
            assert(c.allowance(owner, spender) == allowanceBefore);
        }
    }

    receive() external payable {}
}

