contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address alice, address bob, uint256 amount) public {
        // alice must be non-zero so the mint succeeds, and we drive c only through its public surface.
        require(alice != address(0), "alice zero");
        require(bob != address(0), "bob zero");
        require(amount > 0, "amount zero");

        // Need alice to have some balance to transfer from.  Mint to alice by
        // calling a state-changing function on c directly (top-level statement).
        // mintSynth requires msg.sender to be a curated pool; the test contract
        // is not one, so it will revert.  Instead, exercise the transfer rule
        // only when it is reachable: require that c.mintSynth reverts does not
        // give us setup.  So we instead test the transfer path after an approve/
        // transferFrom self-call pattern is impossible without balance.
        //
        // The only way to obtain an initial balance for alice through the public
        // surface without being a curator is to have alice == address(this)?
        // But the test contract cannot mint to itself either.  Hence the only
        // universally reachable transfer is the zero-amount / insufficient-balance
        // case, which must revert.  Use that as the general rule.

        uint256 aliceBefore = c.balanceOf(alice);
        uint256 bobBefore = c.balanceOf(bob);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.transferFrom(alice, bob, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 aliceAfter = c.balanceOf(alice);
        uint256 bobAfter = c.balanceOf(bob);
        uint256 supplyAfter = c.totalSupply();

        // General conservation rule: whether or not the call reverts, total
        // supply is unchanged, and on success balances move by exactly the
        // transferred amount.
        assert(
            supplyAfter == supplyBefore &&
            (
                reverted
                    ? (aliceAfter == aliceBefore && bobAfter == bobBefore)
                    : (aliceBefore >= amount &&
                       aliceAfter == aliceBefore - amount &&
                       bobAfter == bobBefore + amount)
            )
        );
    }

    receive() external payable {}
}

